B=[
('الْمُعَلِّمُ','Öğretmen',[
('كَانَ الْحَجَّاجُ بْنُ يُوسُفَ الثَّقَفِيُّ فِي شَبَابِهِ مُعَلِّمًا لِلصِّبْيَانِ فِي الطَّائِفِ.','Haccâc b. Yûsuf es-Sekafî gençliğinde Tâif’te çocuklara öğretmenlik yapardı.'),
('وَكَانَ فَصِيحًا ذَكِيًّا، شَدِيدَ الطُّمُوحِ.','Fasih, zeki ve çok hırslıydı.'),
('فَذَهَبَ إِلَى دِمَشْقَ، وَدَخَلَ فِي جَيْشِ الْخَلِيفَةِ عَبْدِ الْمَلِكِ بْنِ مَرْوَانَ.','Dımaşk’a gitti ve halife Abdülmelik b. Mervân’ın ordusuna katıldı.'),
('فَرَأَى الْخَلِيفَةُ فِيهِ الْحَزْمَ وَالشِّدَّةَ، فَقَرَّبَهُ.','Halife onda kararlılık ve sertlik gördü ve onu yanına yaklaştırdı.'),
('وَكَانَتِ الدَّوْلَةُ يَوْمَئِذٍ مُنْقَسِمَةً، وَفِي مَكَّةَ خَلِيفَةٌ آخَرُ هُوَ عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ.','Devlet o gün bölünmüştü; Mekke’de başka bir halife, Abdullah b. Zübeyr vardı.')]),
('حِصَارُ مَكَّةَ','Mekke kuşatması',[
('فَأَرْسَلَ عَبْدُ الْمَلِكِ الْحَجَّاجَ بِجَيْشٍ إِلَى مَكَّةَ.','Abdülmelik Haccâc’ı bir orduyla Mekke’ye gönderdi.'),
('فَحَاصَرَهَا أَشْهُرًا، وَرَمَاهَا بِالْمَنْجَنِيقِ حَتَّى أَصَابَ الْكَعْبَةَ.','Onu aylarca kuşattı ve mancınıkla taşa tuttu; taşlar Kâbe’ye bile isabet etti.'),
('وَكَانَتْ أَسْمَاءُ بِنْتُ أَبِي بَكْرٍ، أُمُّ ابْنِ الزُّبَيْرِ، عَجُوزًا عَمْيَاءَ.','Ebû Bekir’in kızı, İbn Zübeyr’in annesi Esmâ yaşlı ve kördü.'),
('فَقَالَ لَهَا ابْنُهَا: «يَا أُمَّاهُ، خَذَلَنِي النَّاسُ.»','Oğlu ona dedi ki: “Anneciğim, insanlar beni yalnız bıraktı.”'),
('فَقَالَتْ: «إِنْ كُنْتَ عَلَى الْحَقِّ فَامْضِ عَلَيْهِ، وَلَا تُمَكِّنْ مِنْ رَقَبَتِكَ غِلْمَانَ بَنِي أُمَيَّةَ.»','Dedi ki: “Hak üzereysen ona devam et ve boynunu Ümeyyeoğullarının gençlerine teslim etme.”'),
('فَخَرَجَ يُقَاتِلُ حَتَّى قُتِلَ، وَانْتَهَتِ الْفِتْنَةُ بِقَسْوَةٍ شَدِيدَةٍ.','Çıkıp savaştı ve öldürüldü; fitne büyük bir sertlikle sona erdi.')]),
('الْكُوفَةُ','Kûfe',[
('ثُمَّ جَعَلَهُ عَبْدُ الْمَلِكِ وَالِيًا عَلَى الْعِرَاقِ، وَكَانَ أَهْلُهَا كَثِيرِي الثَّوْرَةِ.','Sonra Abdülmelik onu halkı sık sık isyan eden Irak’a vali yaptı.'),
('فَدَخَلَ الْحَجَّاجُ مَسْجِدَ الْكُوفَةِ مُلَثَّمًا، وَصَعِدَ الْمِنْبَرَ، وَسَكَتَ طَوِيلًا.','Haccâc yüzü örtülü hâlde Kûfe mescidine girdi, minbere çıktı ve uzun süre sustu.'),
('ثُمَّ كَشَفَ عَنْ وَجْهِهِ وَخَطَبَ خُطْبَةً مَشْهُورَةً، هَدَّدَ فِيهَا كُلَّ مَنْ يَخْرُجُ عَلَى الدَّوْلَةِ.','Sonra yüzünü açtı ve devlete isyan eden herkesi tehdit ettiği meşhur bir hutbe verdi.'),
('فَخَافَهُ النَّاسُ، وَسَكَنَتِ الثَّوْرَاتُ، وَلَكِنْ بِالْخَوْفِ لَا بِالْحُبِّ.','İnsanlar ondan korktu, isyanlar dindi; ama sevgiyle değil korkuyla.'),
('وَقُتِلَ فِي عَهْدِهِ كَثِيرٌ مِنَ النَّاسِ، وَمِنْهُمُ الْعُلَمَاءُ.','Onun devrinde aralarında âlimlerin de bulunduğu pek çok insan öldürüldü.')]),
('أَعْمَالُهُ','İcraatı',[
('وَلَكِنَّ الْحَجَّاجَ لَمْ يَكُنْ ظَالِمًا فَقَطْ.','Ama Haccâc yalnızca zalim değildi.'),
('فَقَدْ أَمَرَ بِتَنْقِيطِ حُرُوفِ الْمُصْحَفِ وَتَشْكِيلِهِ، حَتَّى لَا يُخْطِئَ النَّاسُ فِي الْقِرَاءَةِ.','İnsanlar okurken hata yapmasın diye Mushaf’ın harflerinin noktalanmasını ve harekelenmesini emretti.'),
('وَبَنَى مَدِينَةَ وَاسِطٍ، وَحَفَرَ الْأَنْهَارَ، وَأَصْلَحَ الزِّرَاعَةَ.','Vâsıt şehrini kurdu, kanallar kazdı ve tarımı düzeltti.'),
('وَأَرْسَلَ مُحَمَّدَ بْنَ الْقَاسِمِ فَفَتَحَ بِلَادَ السِّنْدِ.','Muhammed b. Kâsım’ı gönderdi; o da Sind diyarını fethetti.'),
('فَاخْتَلَفَ النَّاسُ فِيهِ: فَمِنْهُمْ مَنْ يَذْكُرُ ظُلْمَهُ، وَمِنْهُمْ مَنْ يَذْكُرُ أَعْمَالَهُ.','İnsanlar onun hakkında ayrıldılar: kimisi zulmünü anar, kimisi icraatını.'),
('وَمَاتَ سَنَةَ خَمْسٍ وَتِسْعِينَ، وَيَرَى زَيْدَانُ فِي قِصَّتِهِ دَرْسًا: أَنَّ الْقُوَّةَ بِلَا رَحْمَةٍ تَبْنِي الدَّوْلَةَ وَتَهْدِمُ الْقُلُوبَ.','95 yılında öldü; Zeydân onun hikâyesinde bir ders görür: Merhametsiz güç devleti kurar ama kalpleri yıkar.')]),
]
